<script lang="ts">
	import { replaceState } from "$app/navigation";
	import { page } from "$app/state";
	import { API, Constants } from "$lib";
	import Grid from "$lib/components/ui/Grid.svelte";
	import * as Empty from "$lib/components/ui/empty";
	import Spinner from "$lib/components/ui/spinner/spinner.svelte";
	import { Button } from "$lib/components/ui/button";
	import { prefs } from "$lib/stores";
	import { onMount } from "svelte";
	import { HTTPError } from "$lib/HTTP";
	import { createSafeReadOwner } from "$platform/safe-read-owner";
	import { requireReadAcknowledgement, readFailure } from "$platform/mutation-feedback";
	import ErrorComponent from "./ErrorComponent.svelte";
	import LatestUpdatesGridEntry from "./LatestUpdatesGridEntry.svelte";
	import LatestUpdatesGridSkeleton from "./LatestUpdatesGridSkeleton.svelte";
	import MangaSearchEntryCard from "./MangaSearchEntryCard.svelte";
	import MangaSearchEntrySkeleton from "./MangaSearchEntrySkeleton.svelte";
	let feed = $state<ChapterFeedResponse>(), entries = $state<Chapter[]>([]), idMap = $state<Record<string, undefined>>({});
	let isMounted = $state(false), isLoading = $state(false), isCollapsed = $state(false), footerRef = $state<HTMLElement>();
	let error = $state<Constants.Error.Error>();
	const reads = createSafeReadOwner();
	const query = (n?: number) => { const q = new URLSearchParams(); prefs.applyMangaPreferences(q); prefs.applyChapterPreferences(q); if (n) q.set("page", n.toString()); q.set("limit", "70"); return q; };
	const queryKey = () => JSON.stringify([window.location.href, [...query().entries()].filter(([key]) => key !== "page")]);
	onMount(() => {
		const state = page.state as { _$LatestUpdatesGrid_feed?: ChapterFeedResponse; _$LatestUpdatesGrid_entries?: Chapter[]; _$LatestUpdatesGrid_idMap?: Record<string, undefined>; _$LatestUpdatesGrid_context?: string };
		if (state._$LatestUpdatesGrid_context === queryKey() && state._$LatestUpdatesGrid_feed && state._$LatestUpdatesGrid_entries && state._$LatestUpdatesGrid_idMap) {
			feed = state._$LatestUpdatesGrid_feed; entries = state._$LatestUpdatesGrid_entries; idMap = state._$LatestUpdatesGrid_idMap; isMounted = true;
		} else void load();
	});
	const load = async (n?: number) => {
		if (isLoading || !reads.isLive()) return false;
		const key = queryKey(), intent = reads.capture(() => queryKey() === key), href = window.location.href;
		isLoading = true; error = undefined; if (!entries.length) isMounted = false;
		try {
			const body = requireReadAcknowledgement(await API.Chapter.LatestUpdates(query(n)));
			if (!intent.alive()) { if (intent.current()) error = readFailure(new HTTPError(409, "The route or requested filters changed while loading. Retry the current updates.", "Updates load interrupted")); return false; }
			if (!Array.isArray(body.data)) throw new HTTPError(502, "The server returned an invalid update feed. Retry after checking service availability.");
			feed = body;
			for (const chapter of body.data) { const id = chapter.relationships.manga.id; if (!(id in idMap)) { idMap[id] = undefined; entries.push(chapter); } }
			entries = entries;
			replaceState(href, { ...page.state, _$LatestUpdatesGrid_feed: $state.snapshot(feed), _$LatestUpdatesGrid_entries: $state.snapshot(entries), _$LatestUpdatesGrid_idMap: $state.snapshot(idMap), _$LatestUpdatesGrid_context: key });
			return true;
		} catch (cause) {
			if (intent.current()) error = intent.alive() ? readFailure(cause) : readFailure(new HTTPError(409, "The update request no longer matches the current route or filters. Retry the current updates."));
			return false;
		} finally { if (intent.current()) { isLoading = false; isMounted = true; } }
	};
	const retryUpdates = () => load(entries.length && feed ? feed.page + 1 : undefined);
	$effect(() => {
		const target = footerRef;
		if (!target || isCollapsed || error) return;
		let disposed = false;
		const observer = new IntersectionObserver(async ([entry]) => {
			if (disposed || !entry.isIntersecting || !feed || isCollapsed || isLoading || error || feed.limit * feed.page >= feed.total) return;
			const success = await load(feed.page + 1);
			if (disposed || !success || !feed?.data?.length) observer.disconnect();
		}, { rootMargin: window.innerHeight + "px" });
		observer.observe(target); return () => { disposed = true; observer.disconnect(); };
	});
</script>

{#if error}
	<ErrorComponent {error} />
	<Button variant="outline" disabled={isLoading} onclick={retryUpdates}>Retry updates</Button>
{/if}
{#if isMounted}
	{#if entries.length}
		<Grid class="gap-3" breakpoints={Constants.MangaGridBreakpoints}>
			{#each entries as chapter (chapter)}
				<article>
					<MangaSearchEntryCard manga={chapter.relationships.manga} isGrid />
					<LatestUpdatesGridEntry {chapter} />
				</article>
			{/each}
		</Grid>
	{:else if !error}
		<Empty.Root>
			<Empty.Header>
				<Empty.Title>No updates found</Empty.Title>
				<Empty.Description>
					The database may still be updating, or no entries matching your filters were found.
				</Empty.Description>
			</Empty.Header>
		</Empty.Root>
	{/if}
{:else}
	<Grid class="gap-3" breakpoints={Constants.MangaGridBreakpoints}>
		{#each Array.from({ length: 21 })}
			<article>
				<MangaSearchEntrySkeleton isGrid />
				<LatestUpdatesGridSkeleton />
			</article>
		{/each}
	</Grid>
{/if}

{#if !isCollapsed && feed && feed.limit * feed.page < feed.total}
	<div class:h-0.5={!isLoading} bind:this={footerRef}>
		{#if isLoading}
			<Empty.Root>
				<Spinner class="size-10" />
			</Empty.Root>
		{/if}
	</div>
{/if}
